import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CircleGeometry,
    Shape,
    ShapeGeometry,
  } = THREE;

  const root = new Group();
  const content = new Group();
  const timelines = [];
  const ownedGeometries = [];
  const ownedMaterials = [];
  let loadedTexture = null;
  let disposed = false;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = {
    ink: visualSpec.colors?.ink ?? '#16161d',
    paper: visualSpec.colors?.paper ?? '#e8ecf2',
    accent: visualSpec.colors?.accent ?? '#ff2a38',
    surface: visualSpec.colors?.surface ?? '#0b0b10',
  };

  const makeMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.push(material);
    return material;
  };

  const makeGeometry = (geometry) => {
    ownedGeometries.push(geometry);
    return geometry;
  };

  const roundedCapsule = (width, height, radius) => {
    const shape = new Shape();
    const x = width * 0.5;
    const y = height * 0.5;
    const r = Math.min(radius, y, x);

    shape.moveTo(-x + r, -y);
    shape.lineTo(x - r, -y);
    shape.quadraticCurveTo(x, -y, x, -y + r);
    shape.lineTo(x, y - r);
    shape.quadraticCurveTo(x, y, x - r, y);
    shape.lineTo(-x + r, y);
    shape.quadraticCurveTo(-x, y, -x, y - r);
    shape.lineTo(-x, -y + r);
    shape.quadraticCurveTo(-x, -y, -x + r, -y);

    return makeGeometry(new ShapeGeometry(shape));
  };

  const stage = new Group();
  root.add(stage);

  const gradientStops = Array.isArray(visualSpec.gradientStops)
    ? visualSpec.gradientStops
    : [colors.surface, colors.ink];

  const stopColor = (stop, fallback) => {
    if (typeof stop === 'string') return stop;
    if (stop && typeof stop.color === 'string') return stop.color;
    return fallback;
  };

  const gradientMaterial = makeMaterial();
  const gradientUv = uv();
  const first = color(stopColor(gradientStops[0], colors.surface));
  const middle = color(
    stopColor(
      gradientStops[Math.floor(gradientStops.length * 0.5)],
      colors.ink,
    ),
  );
  const last = color(
    stopColor(gradientStops[gradientStops.length - 1], colors.ink),
  );

  const lowerBlend = smoothstep(0.0, 0.58, gradientUv.y);
  const upperBlend = smoothstep(0.42, 1.0, gradientUv.y);
  gradientMaterial.colorNode = mix(
    mix(first, middle, lowerBlend),
    last,
    upperBlend,
  );

  const backdrop = new Mesh(
    makeGeometry(new PlaneGeometry(7, 6)),
    gradientMaterial,
  );
  backdrop.position.set(0, 0, -2.5);
  stage.add(backdrop);

  const shadowMaterial = makeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
  });
  const shadow = new Mesh(
    makeGeometry(new CircleGeometry(1.45, 48)),
    shadowMaterial,
  );
  shadow.scale.set(1.55, 0.34, 1);
  shadow.position.set(0, -0.42, -0.08);
  stage.add(shadow);

  const edgeMaterial = makeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.94,
  });
  const edge = new Mesh(roundedCapsule(2.62, 0.82, 0.41), edgeMaterial);
  edge.position.set(0, 0, 0.02);
  stage.add(edge);

  const faceMaterial = makeMaterial({
    color: colors.paper,
    roughness: 0.72,
    metalness: 0.18,
  });
  const face = new Mesh(roundedCapsule(2.48, 0.68, 0.34), faceMaterial);
  face.position.set(0, 0, 0.055);
  stage.add(face);

  content.position.set(0, 0, 0);
  content.add(stage);
  root.add(content);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const role = item.role ?? 'caption';
    const fontSize = item.typography?.fontSize ??
      (role === 'headline' ? 0.34 : 0.09);

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: role === 'headline' ? colors.ink : colors.paper,
      align: item.typography?.align ?? 'center',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx,
    });

    textObject.position.set(0, -fontSize * 0.34, 0.11);
    content.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) return;
      loadedTexture = texture;
      faceMaterial.map = texture;
      faceMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    if (!primitive || !primitive.name) continue;
    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result?.timeline) timelines.push(result.timeline);
    if (result?.cleanup) timelines.push({ kill: result.cleanup });
  }

  const entrance = gsap.fromTo(
    content.position,
    { y: 0.15 },
    {
      y: 0,
      duration: 0.7,
      ease: 'power3.out',
    },
  );
  timelines.push(entrance);

  const state = {
    hovered: false,
    focused: false,
  };

  const setHover = (active) => {
    state.hovered = Boolean(active);
    gsap.to(content.position, {
      y: state.hovered ? 0.15 : 0,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: true,
    });
  };

  const setFocus = (active) => {
    state.focused = Boolean(active);
    gsap.to(edgeMaterial, {
      opacity: state.focused ? 1 : 0.94,
      duration: 0.2,
      ease: 'power2.out',
      overwrite: true,
    });
  };

  const press = () => {
    gsap.timeline()
      .to(content.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out',
      })
      .to(content.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.34,
        ease: 'back.out(2.2)',
      });
    ctx.emit('hub-collection.select', { node: root });
  };

  root.userData.handlers = {
    hover: setHover,
    mouseenter: () => setHover(true),
    mouseleave: () => setHover(false),
    focus: setFocus,
    blur: () => setFocus(false),
    click: press,
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    gsap.killTweensOf(content.position);
    gsap.killTweensOf(content.scale);
    gsap.killTweensOf(edgeMaterial);

    for (const geometry of ownedGeometries) geometry.dispose();
    for (const material of ownedMaterials) material.dispose();

    if (loadedTexture?.dispose) loadedTexture.dispose();
  };

  return root;
}
